# Generated by sync_menu_ui; edit canonical sources.
"""The camera profiles' floppy in the window's header (decisions of 2026-10-12, mockup profils/1_disquette.png).

The gear's square button (panel_buttons.gear) around a floppy drawn only from flat shapes, as the gear is, so the game
needs no image: a hull outline with its corner cut, a solid shutter with its hole at the top, a solid label at the
bottom. Built collapsed in the camera mods' headers (sync_menu_ui.py); the profile form shows it where a profile can be
kept (panel_profile_form.py).
"""

from . import panel_buttons as b, panel_theme as t, panel_widgets as w

# The mockup's floppy in its hull's proportions (profils.css, .floppy-icon), the hull as large as the gear's icon.
SIDE = t.GEAR_ICON_SIZE
SHUTTER_LEFT, SHUTTER_WIDTH, SHUTTER_HEIGHT = round(SIDE * 0.18), round(SIDE * 0.52), round(SIDE * 0.38)
HOLE_WIDTH, HOLE_HEIGHT = round(SHUTTER_WIDTH * 0.22), round(SHUTTER_HEIGHT * 0.6)
HOLE_TOP, HOLE_LEFT = round(SHUTTER_HEIGHT * 0.2), SHUTTER_LEFT + round(SHUTTER_WIDTH * 0.64)
LABEL_SIDE, LABEL_HEIGHT, LABEL_BOTTOM = round(SIDE * 0.12), round(SIDE * 0.3), round(SIDE * 0.1)
# The cut corner: a square of the button's fill, turned by 45° and centred on the hull's corner.
CUT = round(SIDE * 0.32)
# The shapes in the icon's colour, and those in the button's fill, which hollow or cut the others.
COLOURED, HOLLOWED = ("hull", "shutter", "label"), ("inside", "hole", "cut")


def _shape(icon, widgets, name, width, height, padding, halign, valign):
    shape = w.border(icon, t.COLOR_TEXT_DIM)
    widgets[f"profile:floppy:{name}"] = shape
    w.layer(icon, w.sized(icon, shape, width, height), padding=padding, halign=halign, valign=valign)
    return shape


def _turn(cut):
    cut.SetRenderTransformAngle(45.0)
    cut.SetRenderTranslation(w.vector(CUT / 2, -CUT / 2))


def button(owner, widgets, template):
    frame, fill = w.framed(owner, None, t.STROKE)
    check = w.new("CheckBox", fill)
    check.WidgetStyle.CheckBoxType = b.TOGGLE_BUTTON
    for field, veil in b._STATES:
        tint, alpha = veil or (t.COLOR_INK, 0.0)
        w.style_brush(check.WidgetStyle, field, template, tint, alpha=alpha)
    icon = w.new("Overlay", check)
    hull = w.border(icon, t.COLOR_TEXT_DIM, t.STROKE)
    inside = w.border(hull, t.COLOR_INK)
    hull.SetContent(inside)
    w.layer(icon, hull)
    widgets["profile:floppy:hull"], widgets["profile:floppy:inside"] = hull, inside
    _shape(icon, widgets, "shutter", SHUTTER_WIDTH, SHUTTER_HEIGHT, w.pad(0, 0, 0, SHUTTER_LEFT), "Left", "Top")
    _shape(icon, widgets, "hole", HOLE_WIDTH, HOLE_HEIGHT, w.pad(HOLE_TOP, 0, 0, HOLE_LEFT), "Left", "Top")
    _shape(icon, widgets, "label", SIDE - 2 * LABEL_SIDE, LABEL_HEIGHT, w.pad(0, 0, LABEL_BOTTOM, LABEL_SIDE), "Left",
           "Bottom")
    cut = _shape(icon, widgets, "cut", CUT, CUT, None, "Right", "Top")
    # Without the turn, the corner stays square: the floppy still reads as one.
    w.cosmetic("floppy_cut", lambda: _turn(cut))
    check.SetContent(w.sized(check, icon, SIDE, SIDE))
    check.SetIsChecked(False)
    fill.SetContent(check)
    layers, shade = w.shadowed(owner, frame, t.SHADOW_MD)
    # Slanted, icon included, as the gear beside it.
    w.slant(layers)
    body = w.sized(owner, layers, t.KEY_ICON_SIZE + t.SHADOW_MD, t.KEY_ICON_SIZE + t.SHADOW_MD)
    body.SetVisibility(w.enum("ESlateVisibility", "Collapsed"))
    widgets.update({"profile:floppy": check, "profile:floppy_fill": fill, "profile:floppy_frame": frame,
                    "profile:floppy_shadow": shade, "profile:floppy_body": body})
    paint(widgets)
    return body


def paint(widgets):
    """The gear's colours when its tabs are closed (panel_buttons.paint_gear)."""
    colour, fill = t.COLOR_TEXT_DIM, t.COLOR_OFF
    widgets["profile:floppy_fill"].SetBrushColor(w.linear(fill))
    widgets["profile:floppy_frame"].SetBrushColor(w.linear(colour))
    widgets["profile:floppy_shadow"].SetBrushColor(w.linear(t.COLOR_INK))
    for names, tint in ((COLOURED, colour), (HOLLOWED, fill)):
        for name in names:
            widgets[f"profile:floppy:{name}"].SetBrushColor(w.linear(tint))
